CREATE TABLE IF NOT EXISTS tickets (id TEXT PRIMARY KEY, team TEXT NOT NULL, channel TEXT NOT NULL, requester TEXT NOT NULL, source_key TEXT NOT NULL, text TEXT NOT NULL, category TEXT NOT NULL, route TEXT NOT NULL, priority TEXT NOT NULL CHECK(priority IN ('normal','high')), status TEXT NOT NULL DEFAULT 'open' CHECK(status IN ('open','in_progress','escalated','resolved')), assignee TEXT, thread_ts TEXT, version INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, last_actor TEXT NOT NULL, last_action TEXT NOT NULL DEFAULT 'created', UNIQUE(team,source_key));
CREATE TABLE IF NOT EXISTS ticket_history (sequence INTEGER PRIMARY KEY AUTOINCREMENT, ticket_id TEXT NOT NULL REFERENCES tickets(id), actor TEXT NOT NULL, action TEXT NOT NULL, status TEXT NOT NULL, version INTEGER NOT NULL, at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TRIGGER IF NOT EXISTS ticket_created AFTER INSERT ON tickets BEGIN INSERT INTO ticket_history(ticket_id,actor,action,status,version) VALUES(new.id,new.last_actor,'created',new.status,new.version); END;
CREATE TRIGGER IF NOT EXISTS ticket_changed AFTER UPDATE ON tickets WHEN new.version != old.version BEGIN INSERT INTO ticket_history(ticket_id,actor,action,status,version) VALUES(new.id,new.last_actor,new.last_action,new.status,new.version); END;
CREATE INDEX IF NOT EXISTS tickets_scope ON tickets(team,channel,requester,created_at);
CREATE TABLE IF NOT EXISTS deliveries (team TEXT NOT NULL, source_key TEXT NOT NULL, state TEXT NOT NULL DEFAULT 'attempted', PRIMARY KEY(team,source_key));
